  "atomic_questions": [
    "For the end-of-quarter inventory requirement of 150 units per product, should this be treated as an exact equality (inventory must be exactly 150) or as a minimum (inventory must be at least 150)?"
  ],
  "rationale": "The response asks a single clarification question regarding the nature of the inventory constraint (equality vs. minimum)."
}

